// SymForce runner for the 3D pose-graph benchmark -- the generated-code
// path: the canonical quaternion-vector SE3 residual is defined
// symbolically in ../symforce_gen.py, code-generated by SymForce into
// flattened C++ linearization functions
// (symforce_gen/{between,prior}_residual3_factor.h), and executed by
// SymForce's own C++ sym::Optimizer (LM). Templated over double/float.
//
//   symforce_bench3 <file.g2o> <f64|f32> <poses_out>
//
// JSON {solve_ms, first_iter_ms, iterations, accepted, initial_cost,
// cpus_allowed} on stdout, "x y z qx qy qz qw" lines to poses_out.
// initial_cost is the canonical cost of the initial estimate computed
// by the GENERATED residual functions (in double), which the harness
// asserts equals the reference cost function. SYMFORCE_LAMBDA0
// overrides the initial damping (default 1e-10 per the README's
// initial-damping policy; SymForce ships 1.0).

#include <chrono>
#include <cstdio>
#include <cstdlib>
#include <fstream>
#include <sstream>
#include <string>
#include <vector>

#include <Eigen/Dense>
#include <sym/pose3.h>
#include <sym/util/epsilon.h>
#include <symforce/opt/factor.h>
#include <symforce/opt/key.h>
#include <symforce/opt/optimizer.h>

#include "symforce_gen/between_residual3_factor.h"
#include "symforce_gen/prior_residual3_factor.h"

struct PoseIn {
    Eigen::Vector3d t;
    Eigen::Quaterniond q;
};
struct EdgeIn {
    int a, b;
    Eigen::Vector3d dt;
    Eigen::Quaterniond dq;
    Eigen::Matrix<double, 6, 6> u; // upper sqrt info, info = u^T u
};

static void parse_g2o(const char* path, std::vector<PoseIn>& poses, std::vector<EdgeIn>& edges) {
    std::ifstream f(path);
    std::string line;
    while (std::getline(f, line)) {
        std::istringstream ss(line);
        std::string tag;
        ss >> tag;
        if (tag == "VERTEX_SE3:QUAT") {
            int id;
            double x, y, z, qx, qy, qz, qw;
            ss >> id >> x >> y >> z >> qx >> qy >> qz >> qw;
            if (id != (int)poses.size()) { fprintf(stderr, "non-dense vertices\n"); exit(1); }
            poses.push_back(PoseIn{{x, y, z}, Eigen::Quaterniond(qw, qx, qy, qz).normalized()});
        } else if (tag == "EDGE_SE3:QUAT") {
            EdgeIn e;
            double x, y, z, qx, qy, qz, qw;
            ss >> e.a >> e.b >> x >> y >> z >> qx >> qy >> qz >> qw;
            e.dt = Eigen::Vector3d(x, y, z);
            e.dq = Eigen::Quaterniond(qw, qx, qy, qz).normalized();
            Eigen::Matrix<double, 6, 6> info;
            for (int i = 0; i < 6; i++) {
                for (int j = i; j < 6; j++) {
                    double v;
                    ss >> v;
                    info(i, j) = v;
                    info(j, i) = v;
                }
            }
            e.u = info.llt().matrixU();
            edges.push_back(e);
        }
    }
}

template <typename Scalar>
sym::Pose3<Scalar> make_pose(const Eigen::Vector3d& t, const Eigen::Quaterniond& q) {
    return sym::Pose3<Scalar>(sym::Rot3<Scalar>(q.cast<Scalar>()), t.cast<Scalar>());
}

// Canonical cost of the initial estimate, evaluated by the GENERATED
// residual functions in double precision -- the harness cross-checks
// this against the reference cost function.
static double initial_cost(const std::vector<PoseIn>& poses, const std::vector<EdgeIn>& edges) {
    double cost = 0.0;
    for (const EdgeIn& e : edges) {
        Eigen::Matrix<double, 6, 1> res;
        sym::BetweenResidual3Factor<double>(
            make_pose<double>(poses[e.a].t, poses[e.a].q),
            make_pose<double>(poses[e.b].t, poses[e.b].q),
            make_pose<double>(e.dt, e.dq), e.u, &res);
        cost += res.squaredNorm();
    }
    Eigen::Matrix<double, 6, 1> res;
    sym::PriorResidual3Factor<double>(
        make_pose<double>(poses[0].t, poses[0].q),
        make_pose<double>(poses[0].t, poses[0].q), &res);
    cost += res.squaredNorm();
    return cost;
}

struct RunResult {
    double ms;
    int accepted, total;
};

template <typename Scalar>
RunResult solve(const std::vector<PoseIn>& poses, const std::vector<EdgeIn>& edges,
                int max_iters, std::vector<PoseIn>* out) {
    sym::Values<Scalar> values;
    for (size_t i = 0; i < poses.size(); i++) {
        values.Set({'P', (int64_t)i}, make_pose<Scalar>(poses[i].t, poses[i].q));
    }
    for (size_t k = 0; k < edges.size(); k++) {
        const EdgeIn& e = edges[k];
        values.Set({'M', (int64_t)k}, make_pose<Scalar>(e.dt, e.dq));
        values.Set({'U', (int64_t)k},
                   Eigen::Matrix<Scalar, 6, 6>(e.u.cast<Scalar>()));
    }
    values.Set({'q'}, make_pose<Scalar>(poses[0].t, poses[0].q));

    std::vector<sym::Factor<Scalar>> factors;
    factors.reserve(edges.size() + 1);
    for (size_t k = 0; k < edges.size(); k++) {
        const EdgeIn& e = edges[k];
        factors.push_back(sym::Factor<Scalar>::Hessian(
            sym::BetweenResidual3Factor<Scalar>,
            {{'P', e.a}, {'P', e.b}, {'M', (int64_t)k}, {'U', (int64_t)k}},
            {{'P', e.a}, {'P', e.b}}));
    }
    factors.push_back(sym::Factor<Scalar>::Hessian(
        sym::PriorResidual3Factor<Scalar>, {{'P', 0}, {'q'}}, {{'P', 0}}));

    auto params = sym::DefaultOptimizerParams();
    params.iterations = max_iters;
    // Same termination class as the other systems.
    params.early_exit_min_reduction = 1e-5;
    // Problem-appropriate initial damping (see the README policy;
    // SymForce ships initial_lambda = 1.0).
    params.initial_lambda = 1e-10;
    if (const char* l = getenv("SYMFORCE_LAMBDA0")) {
        params.initial_lambda = atof(l);
    }

    sym::Optimizer<Scalar> optimizer(params, std::move(factors));
    auto t0 = std::chrono::steady_clock::now();
    auto stats = optimizer.Optimize(values);
    double ms = std::chrono::duration<double, std::milli>(std::chrono::steady_clock::now() - t0).count();

    int accepted = 0;
    for (const auto& it : stats.iterations) {
        if (it.update_accepted) accepted++;
    }
    if (out) {
        out->resize(poses.size());
        for (size_t i = 0; i < poses.size(); i++) {
            const auto p = values.template At<sym::Pose3<Scalar>>({'P', (int64_t)i});
            (*out)[i].t = p.Position().template cast<double>();
            (*out)[i].q = p.Rotation().Quaternion().template cast<double>();
        }
    }
    return RunResult{ms, accepted, (int)stats.iterations.size()};
}

template <typename Scalar>
void run(const char* g2o, const char* poses_out) {
    std::vector<PoseIn> poses;
    std::vector<EdgeIn> edges;
    parse_g2o(g2o, poses, edges);

    RunResult first = solve<Scalar>(poses, edges, 1, nullptr);
    std::vector<PoseIn> result;
    RunResult full = solve<Scalar>(poses, edges, 100, &result);

    std::ofstream out(poses_out);
    for (const PoseIn& p : result) {
        out << p.t.x() << " " << p.t.y() << " " << p.t.z() << " "
            << p.q.x() << " " << p.q.y() << " " << p.q.z() << " " << p.q.w() << "\n";
    }
    std::string cpus = "?";
    std::ifstream st("/proc/self/status");
    std::string l;
    while (std::getline(st, l)) {
        if (l.rfind("Cpus_allowed_list:", 0) == 0) {
            cpus = l.substr(l.find_last_of(" \t") + 1);
        }
    }
    printf("{\"solve_ms\": %.3f, \"first_iter_ms\": %.3f, \"iterations\": %d, \"accepted\": %d, "
           "\"initial_cost\": %.6f, \"cpus_allowed\": \"%s\"}\n",
           full.ms, first.ms, full.total, full.accepted, initial_cost(poses, edges), cpus.c_str());
}

int main(int argc, char** argv) {
    // Silence SymForce's atexit profiling table (it would interleave
    // with the JSON protocol line on stdout).
    setenv("SYMFORCE_TIC_TOC_QUIET", "1", 0);
    if (argc < 4) { fprintf(stderr, "usage: %s <g2o> <f64|f32> <poses_out>\n", argv[0]); return 1; }
    if (std::string(argv[2]) == "f32") {
        run<float>(argv[1], argv[3]);
    } else {
        run<double>(argv[1], argv[3]);
    }
    return 0;
}
